package dev.kelmagic.gametest;
import com.mojang.authlib.GameProfile;
import dev.kelmagic.artifact.*;
import dev.kelmagic.server.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("kelmagic_artifact") @PrefixGameTestTemplate(false)
public final class ArtifactGameTests {
    private static final class Fixture extends FakePlayer {Fixture(ServerLevel l,GameProfile p){super(l,p);try{var f=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(this,0);}catch(ReflectiveOperationException ex){throw new IllegalStateException(ex);}}@Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource s){return false;}}
    private static ServerPlayer player(GameTestHelper h){var p=new Fixture(h.getLevel(),new GameProfile(UUID.randomUUID(),"ArtifactQA"));p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setPos(h.absoluteVec(new Vec3(3.5,1,3.5)));p.setHealth(20);p.setData(MagicAttachments.MANA,new MagicAttachments.Mana(5,false));return p;}
    private static void equip(ServerPlayer p,String set){for(var it:ArtifactContent.ARMOR.get(set)){var armor=it.get();p.setItemSlot(armor.getEquipmentSlot(),new ItemStack(armor));}}
    private static ArtifactBlockEntity block(GameTestHelper h,Block b,int x,int y,int z){h.setBlock(x,y,z,b);return (ArtifactBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(x,y,z)));}
    @GameTest(template="empty",timeoutTicks=40) public static void registered_content(GameTestHelper h){h.assertTrue(ArtifactContent.ITEMS.size()==55,"55 items / blocks / armor pieces registered");h.assertTrue(ArtifactContent.ARMOR.size()==4,"Four sets");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void bowl_roundtrip(GameTestHelper h){var be=block(h,ArtifactContent.BOWL_DEEP.get(),2,1,2);be.owner=UUID.randomUUID();be.trusted.add(UUID.randomUUID());be.mana=411.5;var tag=be.saveWithoutMetadata(h.getLevel().registryAccess());var copy=new ArtifactBlockEntity(be.getBlockPos(),be.getBlockState());copy.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(copy.mana==411.5&&copy.owner.equals(be.owner)&&copy.trusted.equals(be.trusted),"Mana, owner, trust survive saving");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void corrupt_bowl_clamped(GameTestHelper h){var be=block(h,ArtifactContent.BOWL_SMALL.get(),2,1,2);var tag=be.saveWithoutMetadata(h.getLevel().registryAccess());tag.putDouble("Mana",Double.NaN);be.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(be.mana==0,"NaN rejected");tag.putDouble("Mana",999999);be.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(be.mana==32,"Capacity enforced");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void negation_denies_all_statuses(GameTestHelper h){var p=player(h);equip(p,"strict_negation");h.assertTrue(ArtifactRuntime.immune(p),"Full negation recognized");h.assertTrue(!p.addEffect(new MobEffectInstance(MobEffects.REGENERATION,200)),"Beneficial denied");h.assertTrue(!p.addEffect(new MobEffectInstance(MobEffects.POISON,200)),"Harmful denied");h.assertTrue(!ArcaneFire.ignite(p),"Arcane fire denied");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void negation_clears_existing(GameTestHelper h){var p=player(h);p.addEffect(new MobEffectInstance(MobEffects.REGENERATION,200));p.addEffect(new MobEffectInstance(MobEffects.POISON,200));equip(p,"strict_negation");ArtifactRuntime.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(p.getActiveEffects().isEmpty(),"Existing effects cleared");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void partial_negation_not_immune(GameTestHelper h){var p=player(h);var item=ArtifactContent.ARMOR.get("strict_negation").getFirst().get();p.setItemSlot(item.getEquipmentSlot(),new ItemStack(item));h.assertTrue(!ArtifactRuntime.immune(p),"Partial set not immune");p.addEffect(new MobEffectInstance(MobEffects.POISON,200));h.assertTrue(p.hasEffect(MobEffects.POISON),"Partial effects allowed");h.assertTrue(p.getEffect(MobEffects.POISON).getDuration()<200,"Partial effects shortened");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void deep_source_upgrade(GameTestHelper h){var p=player(h);equip(p,"deep_source");h.assertTrue(MagicServer.equipmentBonus(p)==16,"Deep source adds 16 mana");h.assertTrue(MagicServer.maximum(p)==21,"No hidden reserve");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void portal_base_detected(GameTestHelper h){var be=block(h,ArtifactContent.WARD.get(),2,1,2);h.assertTrue(ArtifactWorld.portalBlocked(h.getLevel(),Vec3.atBottomCenterOf(be.getBlockPos().above())),"Ward under endpoint blocks it");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void permission_obelisk(GameTestHelper h){var p=player(h);var be=block(h,ArtifactContent.ACCESS.get(),2,1,2);be.owner=UUID.randomUUID();ArtifactWorld.register(h.getLevel(),be);h.assertTrue(!ArtifactWorld.allowed(p,be.getBlockPos()),"Stranger blocked");be.trusted.add(p.getUUID());h.assertTrue(ArtifactWorld.allowed(p,be.getBlockPos()),"Trusted player allowed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void mute_requires_charge(GameTestHelper h){var be=block(h,ArtifactContent.MUTE.get(),2,1,2);ArtifactWorld.register(h.getLevel(),be);h.assertTrue(!ArtifactWorld.muted(h.getLevel(),Vec3.atCenterOf(be.getBlockPos())),"Empty obelisk inactive");be.active=true;h.assertTrue(ArtifactWorld.muted(h.getLevel(),Vec3.atCenterOf(be.getBlockPos())),"Charged activated obelisk mutes");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void growth_lock_persists(GameTestHelper h){var p=player(h);h.setBlock(2,0,2,Blocks.FARMLAND);h.setBlock(2,1,2,Blocks.WHEAT);var at=h.absolutePos(new BlockPos(2,1,2));var data=ArtifactSeasons.get(h.getLevel());h.assertTrue(data.toggle(at,p.getUUID(),h.getLevel().getBlockState(at)),"Lock toggled");h.assertTrue(ArtifactSeasons.locked(h.getLevel(),at),"Growth locked");h.assertTrue(!data.toggle(at,UUID.randomUUID(),h.getLevel().getBlockState(at)),"Another owner cannot remove");h.assertTrue(data.toggle(at,p.getUUID(),h.getLevel().getBlockState(at)),"Owner removes");h.assertTrue(!ArtifactSeasons.locked(h.getLevel(),at),"Growth resumed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void bridge_expiry(GameTestHelper h){var be=block(h,ArtifactContent.BRIDGE.get(),2,1,2);be.expires=h.getLevel().getGameTime();ArtifactBlockEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(h.getLevel().getBlockState(be.getBlockPos()).isAir(),"Temporary path expires without drops");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void crystal_roundtrip_and_limit(GameTestHelper h){var p=player(h);var be=block(h,ArtifactContent.CRYSTAL.get(),2,1,2);be.owner=p.getUUID();be.recording=p.getUUID();be.recordingUntil=h.getLevel().getGameTime()+40;h.assertTrue(be.capture(p,List.of("pir","lu","nis")),"Three words accepted");h.assertTrue(be.words.size()==3,"Exactly 3 words");be.capture(p,List.of("pir"));h.assertTrue(be.words.size()==3,"Fourth word not recorded");var tag=be.saveWithoutMetadata(h.getLevel().registryAccess());var copy=new ArtifactBlockEntity(be.getBlockPos(),be.getBlockState());copy.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(copy.words.equals(be.words)&&copy.recording==null,"Formula persists; live recording does not");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void shield_refund_cost(GameTestHelper h){var p=player(h);p.setYRot(0);p.setXRot(0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(ArtifactContent.SHIELD.get()));p.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);p.setData(MagicAttachments.MANA,new MagicAttachments.Mana(0,false));var bolt=ArtifactSpellBolt.TYPE.get().create(h.getLevel());bolt.setPos(p.getEyePosition().add(0,0,1));bolt.cost(6);h.assertTrue(ArtifactCombat.parry(p,bolt),"Parry in early raise window");h.assertTrue(p.getData(MagicAttachments.MANA).current()==3,"Refund exactly half cost");h.assertTrue(p.getCooldowns().isOnCooldown(ArtifactContent.SHIELD.get()),"Five-second cooldown applied");h.assertTrue(bolt.isRemoved(),"Projectile consumed, cannot refund twice");h.succeed();}

    @GameTest(template="empty",timeoutTicks=60) public static void crystal_uses_only_bowl(GameTestHelper h){var p=player(h);for(int x=0;x<8;x++)for(int z=0;z<8;z++)h.setBlock(x,0,z,Blocks.STONE);var bowl=block(h,ArtifactContent.BOWL.get(),3,1,3);var crystal=block(h,ArtifactContent.CRYSTAL.get(),3,2,3);block(h,ArtifactContent.STRIKER.get(),3,3,3);bowl.owner=p.getUUID();bowl.mana=50;crystal.owner=p.getUUID();crystal.words=List.of("pir");double personal=p.getData(MagicAttachments.MANA).current();crystal.strike();h.assertTrue(bowl.mana==47,"Crystal debits exact 3 mana from bowl");h.assertTrue(p.getHealth()==20&&p.getData(MagicAttachments.MANA).current()==personal,"No hidden player payment");h.succeed();}
    @GameTest(template="empty",timeoutTicks=60) public static void crystal_no_credit(GameTestHelper h){var p=player(h);var bowl=block(h,ArtifactContent.BOWL.get(),3,1,3);var crystal=block(h,ArtifactContent.CRYSTAL.get(),3,2,3);block(h,ArtifactContent.STRIKER.get(),3,3,3);bowl.owner=p.getUUID();bowl.mana=2;crystal.owner=p.getUUID();crystal.words=List.of("pir");h.assertTrue(!crystal.strike()&&bowl.mana==2,"Insufficient bowl never borrows health");h.succeed();}
    @GameTest(template="empty",timeoutTicks=60) public static void inventory_not_curios(GameTestHelper h){var p=player(h);p.getInventory().setItem(0,new ItemStack(ArtifactContent.DEEP.get()));h.assertTrue(MagicServer.maximum(p)==5,"Inventory ring grants no passive bonus");if(ArtifactAccessories.loaded()){var inv=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();inv.setEquippedCurio("kelmagic_ring",0,new ItemStack(ArtifactContent.DEEP.get()));h.assertTrue(MagicServer.maximum(p)==15,"Equipped active ring grants bonus");inv.setSlotActive("kelmagic_ring",0,false);h.assertTrue(MagicServer.maximum(p)==5,"Inactive slot grants no bonus");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=60) public static void negation_does_not_cancel_price(GameTestHelper h){var p=player(h);equip(p,"strict_negation");float before=p.getHealth();MagicServer.hurtMana(p,2);h.assertTrue(p.getHealth()<before,"Magic immunity cannot evade health price");h.succeed();}
    @GameTest(template="empty",timeoutTicks=60) public static void shield_rear_and_cooldown(GameTestHelper h){var p=player(h);p.setYRot(0);p.setXRot(0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(ArtifactContent.SHIELD.get()));p.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);var bolt=ArtifactSpellBolt.TYPE.get().create(h.getLevel());bolt.setPos(p.getEyePosition().add(0,0,-1));bolt.cost(4);h.assertTrue(!ArtifactCombat.parry(p,bolt),"Back attacks cannot parry");bolt.setPos(p.getEyePosition().add(0,0,1));p.getCooldowns().addCooldown(ArtifactContent.SHIELD.get(),100);h.assertTrue(!ArtifactCombat.parry(p,bolt),"Cooldown prevents second absorption");h.succeed();}

    @GameTest(template="empty",timeoutTicks=40) public static void root_wall_expiry(GameTestHelper h){var be=block(h,ArtifactContent.ROOT_WALL.get(),2,1,2);be.expires=h.getLevel().getGameTime();ArtifactBlockEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(h.getLevel().getBlockState(be.getBlockPos()).isAir(),"Defensive roots expire without drops");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void grove_root_barrier(GameTestHelper h){var p=player(h);ArtifactCombat.rootBarrier(p);int found=0;for(var d:Direction.Plane.HORIZONTAL){var pos=p.blockPosition().relative(d);if(h.getLevel().getBlockState(pos).is(ArtifactContent.ROOT_WALL.get())){found++;var be=(ArtifactBlockEntity)h.getLevel().getBlockEntity(pos);h.assertTrue(be.owner.equals(p.getUUID())&&be.expires>h.getLevel().getGameTime(),"Roots have owner and lifetime");}}h.assertTrue(found==4,"Four defensive root walls placed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void silent_clasp_not_inventory(GameTestHelper h){var p=player(h);p.getInventory().setItem(0,new ItemStack(ArtifactContent.SILENT.get()));h.assertTrue(ArtifactRuntime.canSpeak(p),"Inventory clasp does not prohibit speech");if(ArtifactAccessories.loaded()){var inv=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();inv.setEquippedCurio("kelmagic_charm",0,new ItemStack(ArtifactContent.SILENT.get()));h.assertTrue(!ArtifactRuntime.canSpeak(p),"Equipped clasp prohibits magical speech");h.assertTrue(ArtifactRuntime.canCast(p),"Nonverbal tools remain usable");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void cautious_prevents_health_price(GameTestHelper h){var p=player(h);p.setData(MagicAttachments.MANA,new MagicAttachments.Mana(2,false));if(ArtifactAccessories.loaded()){var inv=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();inv.setEquippedCurio("kelmagic_ring",0,new ItemStack(ArtifactContent.CAUTIOUS.get()));h.assertTrue(!ArtifactRuntime.canPayWord(p,"pir"),"Unaffordable word rejected before health payment");h.assertTrue(ArtifactRuntime.canPayWord(p,"lu"),"Affordable word accepted");}h.succeed();}
}
